dtsPropsFor.Button:
/** Visual style variant. */
variant?: 'default' | 'destructive' | 'outline' | 'secondary' | 'ghost' | 'link';
/** Size preset. `icon` is a square icon-only button. */
size?: 'default' | 'sm' | 'lg' | 'icon';
className?: string;
disabled?: boolean;
type?: 'button' | 'submit' | 'reset';
onClick?: React.MouseEventHandler<HTMLButtonElement>;
children?: React.ReactNode;

dtsPropsFor.Badge:
/** Visual style variant. */
variant?: 'default' | 'secondary' | 'destructive' | 'success' | 'warning' | 'outline';
className?: string;
children?: React.ReactNode;

dtsPropsFor.Input:
type?: React.HTMLInputTypeAttribute;
placeholder?: string;
value?: string | number;
defaultValue?: string | number;
disabled?: boolean;
className?: string;
onChange?: React.ChangeEventHandler<HTMLInputElement>;

dtsPropsFor.Label:
htmlFor?: string;
className?: string;
children?: React.ReactNode;

dtsPropsFor.Skeleton:
/** Accessible label announced by screen readers. Defaults to "Cargando…". Pass aria-hidden for purely decorative skeletons. */
label?: string;
className?: string;

dtsPropsFor.Logo:
/** Layout. `horizontal`/`vertical` render the full "TurnoGol" wordmark; `icon`/`vector` render the "TG" monogram. */
variant?: 'vertical' | 'horizontal' | 'icon' | 'vector';
className?: string;
iconClassName?: string;
/** Tailwind text-color class for the wordmark. Defaults to "text-slate-900". */
textClassName?: string;

dtsPropsFor.EmptyState:
/** Lucide icon shown in a circular slot above the title. */
icon?: React.ComponentType<{ className?: string }>;
/** Decorative inline SVG; takes precedence over `icon`. */
illustration?: React.ReactNode;
title: string;
description?: string;
/** Call-to-action, typically a <Button> or link. */
action?: React.ReactNode;
className?: string;

dtsPropsFor.ErrorState:
/** `full` is a full-page error; `contained` (default) fills its parent; `inline` is a compact red box. */
variant?: 'full' | 'contained' | 'inline';
title: string;
description?: string;
/** Error reference code shown in small print. */
digest?: string;
onRetry?: () => void;
/** Retry button label. Defaults to "Reintentar". */
retryLabel?: string;
/** Secondary link target (e.g. home). */
secondaryHref?: string;
secondaryLabel?: string;
/** Lucide icon for the secondary link. */
secondaryIcon?: React.ComponentType<{ className?: string }>;

dtsPropsFor.SubmitButton:
children: React.ReactNode;
/** Label shown while the enclosing form's action is pending. Defaults to "Guardando…". */
pendingLabel?: string;
className?: string;
variant?: 'default' | 'destructive' | 'outline' | 'secondary' | 'ghost' | 'link';
size?: 'default' | 'sm' | 'lg' | 'icon';

dtsPropsFor.ConfirmDialog:
open: boolean;
onOpenChange: (open: boolean) => void;
title: string;
description?: React.ReactNode;
/** Extra fields rendered between the description and the footer. */
children?: React.ReactNode;
confirmLabel?: string;
cancelLabel?: string;
/** `destructive` makes the confirm button red. */
variant?: 'default' | 'destructive';
/** Type-to-confirm: confirm stays disabled until this exact phrase is typed. */
confirmationPhrase?: string;
/** Async handler. Return { success:false, error } to keep the dialog open and show the error; void or { success:true } closes it. */
onConfirm: () => Promise<{ success: boolean; error?: string } | void>;

dtsPropsFor.Combobox:
id: string;
options: { value: string; label: string; hint?: string }[];
value: string;
onChange: (value: string) => void;
placeholder?: string;
inputClassName?: string;
/** Empty-results message. Defaults to "Sin resultados". */
emptyMessage?: string;
leadingIcon?: React.ReactNode;
/** Accessible name for the listbox. */
listboxLabel?: string;
/** Adds a first option (value "") that clears the selection, like a "Todas". */
clearOptionLabel?: string;

dtsPropsFor.Dialog:
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
modal?: boolean;
/** Compose with DialogTrigger, DialogContent, DialogHeader, DialogTitle, DialogClose. */
children?: React.ReactNode;

dtsPropsFor.DropdownMenu:
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
modal?: boolean;
dir?: 'ltr' | 'rtl';
/** Compose with DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem. */
children?: React.ReactNode;

dtsPropsFor.Toast:
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
/** Visual style. */
variant?: 'default' | 'success' | 'destructive';
/** Auto-dismiss delay in ms. */
duration?: number;
className?: string;
/** Compose with ToastTitle, ToastDescription, ToastClose inside a ToastProvider + ToastViewport. */
children?: React.ReactNode;
